#pragma once
#include "HostIPCScope.h"
#include <fstream>

namespace coincide::background_host {
// One atomic private checkpoint. This is a bounded correctness foundation, not a high-rate
// append-only database. UI workspace/index/transcript files are never opened by this class.
class Ledger {
public:
    // Internal diagnostics and primitive snapshots only; never serialized or exposed via IPC.
    struct Activity {std::uint64_t copies{},commit_attempts{},reads{},writes{},snapshot_reads{},summary_reads{},receipt_copies{},receipt_bytes{};};
    struct ReadBatch {SessionInfo session;Array events;};
    struct Facts {bool live{},busy{},review{},queue_paused{true},has_prompts{};std::uint64_t queued_count{};bool operator==(const Facts&)const=default;};
private:
    mutable Activity activity_;
    const Scope& scope_;Object original_{nullptr};std::optional<std::string> snapshot_;std::size_t maximum_;
    Object selected(const Key& raw_key,const std::string& raw_epoch)const{const auto key=checked(raw_key);const auto epoch=guid(raw_epoch);const auto all=original_.GetNamedObject(L"sessions");const auto name=winrt::to_hstring(key.name());if(!all.HasKey(name))throw std::runtime_error("This hosted session is unavailable");const auto row=all.GetNamedObject(name);if(text(row,L"epoch",38)!=epoch)throw std::runtime_error("The hosted generation changed; attach current state before sending input");return row;}
    SessionInfo read_summary(const Object& row)const{
        // Read only bounded scalar metadata. Catalogs, prompts, queued payloads and all
        // command/event history stay untouched for summaries and settled empty polls.
        SessionInfo value{key(row.GetNamedObject(L"key")),guid(text(row,L"epoch",38)),row.GetNamedBoolean(L"live",false),row.GetNamedBoolean(L"busy",false),row.GetNamedBoolean(L"review",false),integer(row,L"last"),integer(row,L"acknowledged"),{}};
        value.profile_id=text(row,L"profile_id",80);value.account_scope=text(row,L"account_scope",64);value.launch_fingerprint=text(row,L"launch_fingerprint",64);if(value.launch_fingerprint.empty())value.launch_fingerprint=text(row,L"launch_hash",64);fingerprint(value.account_scope);fingerprint(value.launch_fingerprint);value.queue_paused=row.GetNamedBoolean(L"queue_paused",true);value.models_sequence=integer(row,L"models_sequence");value.queued_count=row.HasKey(L"queued_count")?integer(row,L"queued_count"):row.HasKey(L"queued")?row.GetNamedArray(L"queued").Size():0;value.snapshots_included=false;
        if(value.acknowledged>value.last||value.queued_count>64||value.models_sequence>value.last)throw std::invalid_argument("Invalid hosted session summary");++activity_.summary_reads;return value;
    }
    std::filesystem::path file()const{return scope_.ledger_directory()/L"runtime.json";}
    static void structure(const winrt::Windows::Data::Json::IJsonValue& value,unsigned depth=0,std::size_t* count=nullptr){std::size_t local{};if(!count)count=&local;if(depth>16||++*count>250000)throw std::invalid_argument("The private host ledger exceeds its structural bound");if(value.ValueType()==Type::Object){for(const auto& item:value.GetObject()){if(item.Key().size()>128)throw std::invalid_argument("Host ledger key exceeds its bound");structure(item.Value(),depth+1,count);}}else if(value.ValueType()==Type::Array){if(value.GetArray().Size()>10000)throw std::invalid_argument("Host ledger array exceeds its bound");for(const auto& item:value.GetArray())structure(item,depth+1,count);}else if(value.ValueType()==Type::String){const auto bytes=winrt::to_string(value.GetString());if(bytes.size()>2*1024*1024||bytes.find('\0')!=std::string::npos)throw std::invalid_argument("Host ledger value exceeds its bound");}else if(value.ValueType()==Type::Number&&!std::isfinite(value.GetNumber()))throw std::invalid_argument("Invalid host ledger number");}
    std::optional<std::string> read()const{++activity_.reads;if(!std::filesystem::exists(file()))return{};Handle handle(CreateFileW(file().c_str(),GENERIC_READ|READ_CONTROL,FILE_SHARE_READ,nullptr,OPEN_EXISTING,FILE_FLAG_OPEN_REPARSE_POINT,nullptr));BY_HANDLE_FILE_INFORMATION info{};if(!handle||!GetFileInformationByHandle(handle.value,&info)||(info.dwFileAttributes&(FILE_ATTRIBUTE_DIRECTORY|FILE_ATTRIBUTE_REPARSE_POINT))||info.nNumberOfLinks!=1)throw std::runtime_error("The private host ledger is unavailable or linked");verify_security(handle.value,scope_.sid(),SE_FILE_OBJECT);const auto size=(static_cast<std::uint64_t>(info.nFileSizeHigh)<<32)|info.nFileSizeLow;if(size>maximum_)throw std::runtime_error("The private host ledger exceeds its file size limit");std::string bytes(static_cast<std::size_t>(size),'\0');DWORD copied{};if(size&&(!ReadFile(handle.value,bytes.data(),static_cast<DWORD>(size),&copied,nullptr)||copied!=size))throw std::runtime_error("Could not read the complete private host ledger");if(!local_file::utf8(bytes))throw std::runtime_error("The private host ledger is not UTF-8");return bytes;}
public:
    explicit Ledger(const Scope& scope,std::size_t maximum=16*1024*1024):scope_(scope),maximum_(maximum){if(maximum<4096||maximum>64*1024*1024)throw std::invalid_argument("Invalid host ledger size bound");scope_.prepare_private_directory();snapshot_=read();if(snapshot_){original_=Object::Parse(winrt::to_hstring(*snapshot_));structure(original_);if(text(original_,L"format",80)!="coincide.windows.background-host"||integer(original_,L"version")!=1||text(original_,L"scope",64)!=scope.id())throw std::runtime_error("Unsupported host ledger or physical data scope; the original was preserved");}else{original_=Object{};put(original_,L"format","coincide.windows.background-host");original_.SetNamedValue(L"version",Value::CreateNumberValue(1));put(original_,L"scope",scope.id());original_.SetNamedValue(L"sessions",Object{});original_.SetNamedValue(L"commands",Object{});}}
    Activity activity()const noexcept{return activity_;}
    Facts facts(const std::string& name)const{const auto row=original_.GetNamedObject(L"sessions").GetNamedObject(winrt::to_hstring(name));Facts value;value.live=row.GetNamedBoolean(L"live",false);value.busy=row.GetNamedBoolean(L"busy",false);value.review=row.GetNamedBoolean(L"review",false);value.queue_paused=row.GetNamedBoolean(L"queue_paused",true);value.has_prompts=row.HasKey(L"prompts")&&row.GetNamedArray(L"prompts").Size()!=0;value.queued_count=row.HasKey(L"queued_count")?integer(row,L"queued_count"):row.HasKey(L"queued")?row.GetNamedArray(L"queued").Size():0;return value;}
    bool has_pending_prompts()const{for(const auto& item:original_.GetNamedObject(L"sessions")){const auto row=item.Value().GetObject();if(row.HasKey(L"prompts")&&row.GetNamedArray(L"prompts").Size())return true;}return false;}
    SessionInfo session(const Key& key,const std::string& epoch)const{const auto row=selected(key,epoch);++activity_.snapshot_reads;return info(row);}
    std::vector<SessionInfo> summaries()const{const auto all=original_.GetNamedObject(L"sessions");if(all.Size()>128)throw std::runtime_error("Host session count exceeds its bound");std::vector<SessionInfo> result;result.reserve(all.Size());for(const auto& item:all)result.push_back(read_summary(item.Value().GetObject()));return result;}
    ReadBatch poll(const Key& key,const std::string& epoch,std::uint64_t after)const{
        const auto row=selected(key,epoch);ReadBatch result;result.session=read_summary(row);if(after<result.session.acknowledged||after>result.session.last)throw std::runtime_error("Use the host's durable cursor before replaying events");const auto source=row.GetNamedArray(L"events",Array{});if(static_cast<std::uint64_t>(source.Size())!=result.session.last-result.session.acknowledged)throw std::runtime_error("Host ledger events are incomplete");
        // Durable events are a contiguous prefix following ACK, validated during recovery
        // and every append/compaction. Jump straight past already-fetched receipts.
        const auto first=after-result.session.acknowledged;std::size_t bytes{};for(auto index=static_cast<std::uint32_t>(first);index<source.Size()&&result.events.Size()<128;++index){const auto event=source.GetObjectAt(index);if(integer(event,L"sequence")!=result.session.acknowledged+index+1||text(event,L"epoch",38)!=result.session.epoch)throw std::runtime_error("Host ledger event sequence is invalid");const auto encoded=event.Stringify();const auto size=winrt::to_string(encoded).size();if(bytes+size>3*1024*1024)break;
            // Deep-copy only the selected record, retaining safe unknown wire fields.
            // Neither the returned array nor any nested object aliases original_.
            result.events.Append(Object::Parse(encoded));bytes+=size;++activity_.receipt_copies;activity_.receipt_bytes+=size;
        }return result;
    }
    Object copy()const{++activity_.copies;return Object::Parse(original_.Stringify());}
    void commit(Object next){++activity_.commit_attempts;scope_.verify();structure(next);auto bytes=winrt::to_string(next.Stringify());if(bytes.size()>maximum_)throw std::runtime_error("The durable host event ledger is full; persist and acknowledge events before accepting more work");if(read()!=snapshot_)throw std::runtime_error("The private runtime ledger changed outside this host; work requires review");std::optional<std::string> published(bytes);const auto temporary=scope_.ledger_directory()/winrt::to_hstring("runtime-"+new_guid()+".tmp").c_str();UserSecurity security(scope_.sid());Handle handle(CreateFileW(temporary.c_str(),GENERIC_WRITE|DELETE,FILE_SHARE_READ|FILE_SHARE_DELETE,&security.attributes,CREATE_NEW,FILE_ATTRIBUTE_NORMAL,nullptr));if(!handle)throw std::runtime_error("Could not create the durable host checkpoint");struct Pending{HANDLE file;bool keep{};~Pending(){if(!keep){FILE_DISPOSITION_INFO remove{TRUE};SetFileInformationByHandle(file,FileDispositionInfo,&remove,sizeof(remove));}}}pending{handle.value};DWORD copied{};if(!WriteFile(handle.value,bytes.data(),static_cast<DWORD>(bytes.size()),&copied,nullptr)||copied!=bytes.size()||!FlushFileBuffers(handle.value)||!MoveFileExW(temporary.c_str(),file().c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH))throw std::runtime_error("The host checkpoint did not persist; no completion was acknowledged");pending.keep=true;original_=std::move(next);snapshot_.swap(published);++activity_.writes;}
};
} // namespace coincide::background_host
